import React, {useState, useEffect} from 'react';
import {
 View,
 Text,
 StyleSheet,
 FlatList,
 Image,
 TouchableOpacity,
 ActivityIndicator,
 Alert,
 SafeAreaView,
} from 'react-native';

import Header from '../components/Header';
import CategorySelector from '../components/CategorySelector';
import ProductCard from '../components/ProductCard';
import {fetchProducts} from '../services/api';

const HomeScreen = ({navigation}) => {
 const [products, setProducts] = useState([]);
 const [filteredProducts, setFilteredProducts] = useState([]);
 const [loading, setLoading] = useState(true);
 const [selectedCategory, setSelectedCategory] = useState('Women');
 const [showAllProducts, setShowAllProducts] = useState(false);

 const categories = ['Women', 'Men', 'Accessories', 'Beauty'];

 useEffect(() => {
 loadProducts();
 }, []);

 useEffect(() => {
 filterProducts();
 }, [products, selectedCategory]);

 const loadProducts = async () => {
 try {
 setLoading(true);
 const data = await fetchProducts();
 setProducts(data);
 } catch (error) {
 Alert.alert('Error', 'Failed to load products');
 } finally {
 setLoading(false);
 }
 };

 const filterProducts = () => {
 let filtered = products;

 // Simple category filtering based on product category
 if (selectedCategory !== 'Women') {
 switch (selectedCategory) {
 case 'Men':
 filtered = products.filter(product =>
 product.category === "men's clothing"
 );
 break;
 case 'Accessories':
 filtered = products.filter(product =>
 product.category === 'jewelery'
 );
 break;
 case 'Beauty':
 filtered = products.filter(product =>
 product.category === 'electronics'
 );
 break;
 default:
 filtered = products.filter(product =>
 product.category === "women's clothing"
 );
 }
 } else {
 filtered = products.filter(product =>
 product.category === "women's clothing"
 );
 }

 setFilteredProducts(filtered);
 };

 const handleProductPress = (product) => {
 navigation.navigate('ProductDetails', {product});
 };

 const handleShowMore = () => {
 setShowAllProducts(true);
 };

 const handleShowLess = () => {
 setShowAllProducts(false);
 };

 const handleCategorySelect = (category) => {
 setSelectedCategory(category);
 setShowAllProducts(false); // Reset to horizontal view when changing category
 };

 const featuredProducts = filteredProducts.slice(0, 6);
 const displayProducts = showAllProducts ? filteredProducts : featuredProducts;

 const renderHorizontalProduct = ({item}) => (
 <ProductCard
 product={item}
 onPress={handleProductPress}
 horizontal={true}
 />
 );

 const renderVerticalProduct = ({item}) => (
 <ProductCard
 product={item}
 onPress={handleProductPress}
 horizontal={false}
 />
 );

 if (loading) {
 return (
 <SafeAreaView style={styles.container}>
 <View style={styles.loadingContainer}>
 <ActivityIndicator size="large" color="#333"/>
 </View>
 </SafeAreaView>
 );
 }

 return (
 <SafeAreaView style={styles.container}>
 <Header navigation={navigation}/>

 <FlatList
 showsVerticalScrollIndicator={false}
 ListHeaderComponent={() => (
 <>
 <CategorySelector
 categories={categories}
 selectedCategory={selectedCategory}
 onSelectCategory={handleCategorySelect}
 />

 <View style={styles.coverContainer}>
 <Image
 source={{
 uri: 'https://images.unsplash.com/photo-1441986300917-64674bd600d8?ixlib=rb-4.0.3&auto=format&fit=crop&w=1000&q=80'
 }}
 style={styles.coverImage}
 />
 <View style={styles.coverOverlay}>
 <Text style={styles.coverTitle}>Autumn</Text>
 <Text style={styles.coverTitle}>Collection</Text>
 <Text style={styles.coverSubtitle}>2022</Text>
 </View>
 </View>

 <View style={styles.sectionHeader}>
 <Text style={styles.sectionTitle}>Feature Products</Text>
 <TouchableOpacity onPress={showAllProducts ? handleShowLess : handleShowMore}>
 <Text style={styles.showAllText}>
 {showAllProducts ? 'Show Less' : 'Show all'}
 </Text>
 </TouchableOpacity>
 </View>

 {!showAllProducts && (
 <FlatList
 data={featuredProducts}
 renderItem={renderHorizontalProduct}
 keyExtractor={(item) => item.id.toString()}
 horizontal
 showsHorizontalScrollIndicator={false}
 contentContainerStyle={styles.horizontalList}
 />
 )}
 </>
 )}
 data={showAllProducts ? displayProducts : []}
 renderItem={renderVerticalProduct}
 keyExtractor={(item) => item.id.toString()}
 numColumns={showAllProducts ? 2 : 1}
 key={showAllProducts ? 'vertical' : 'horizontal'}
 contentContainerStyle={styles.verticalList}
 />
 </SafeAreaView>
 );
};

const styles = StyleSheet.create({
 container: {
 flex: 1,
 backgroundColor: '#f8f8f8',
 },
 loadingContainer: {
 flex: 1,
 justifyContent: 'center',
 alignItems: 'center',
 backgroundColor: '#f8f8f8',
 },
 coverContainer: {
 margin: 20,
 borderRadius: 16,
 overflow: 'hidden',
 height: 200,
 },
 coverImage: {
 width: '100%',
 height: '100%',
 },
 coverOverlay: {
 position: 'absolute',
 left: 30,
 top: 30,
 },
 coverTitle: {
 fontSize: 32,
 fontWeight: 'bold',
 color: 'white',
 lineHeight: 36,
 },
 coverSubtitle: {
 fontSize: 32,
 fontWeight: '300',
 color: 'white',
 marginTop: 5,
 },
 sectionHeader: {
 flexDirection: 'row',
 justifyContent: 'space-between',
 alignItems: 'center',
 paddingHorizontal: 20,
 marginBottom: 10,
 },
 sectionTitle: {
 fontSize: 20,
 fontWeight: 'bold',
 color: '#333',
 },
 showAllText: {
 fontSize: 14,
 color: '#999',
 fontWeight: '500',
 },
 horizontalList: {
 paddingHorizontal: 20,
 },
 verticalList: {
 paddingHorizontal: 12,
 },
});

export default HomeScreen;
```
