import React, {useState} from 'react';
import {
 View,
 Text,
 Image,
 TouchableOpacity,
 StyleSheet,
 ScrollView,
 SafeAreaView,
 Dimensions,
 Alert,
} from 'react-native';
import {useCart} from '../context/CartContext';

const {width} = Dimensions.get('window');

const ProductDetailsScreen = ({navigation, route}) => {
 const {product} = route.params;
 const {addToCart} = useCart();
 const [selectedColor, setSelectedColor] = useState(0);

 const colors = ['#D2B48C', '#000000', '#FF6B6B'];

 const handleBackPress = () => {
 navigation.goBack();
 };

 const handleAddToCart = () => {
 addToCart(product);
 Alert.alert(
 'Added to Cart',
 `${product.title} has been added to your cart!`,
 [
 {text: 'Continue Shopping', onPress: () => navigation.goBack()},
 {text: 'View Cart', onPress: () => navigation.navigate('Cart')},
 ]
 );
 };

 return (
 <SafeAreaView style={styles.container}>
 <ScrollView style={styles.scrollView} showsVerticalScrollIndicator={false}>
 <View style={styles.imageContainer}>
 <Image
 source={{uri: product.image}}
 style={styles.productImage}
 resizeMode="cover"
 />
 <TouchableOpacity style={styles.backButton} onPress={handleBackPress}>
 <Text style={styles.backButtonText}>←</Text>
 </TouchableOpacity>
 </View>

 <View style={styles.detailsContainer}>
 <Text style={styles.productTitle}>{product.title}</Text>
 <Text style={styles.productPrice}>$ {product.price.toFixed(2)}</Text>

 <View style={styles.colorSection}>
 <Text style={styles.sectionTitle}>Color</Text>
 <View style={styles.colorOptions}>
 {colors.map((color, index) => (
 <TouchableOpacity
 key={index}
 style={[
 styles.colorOption,
 {backgroundColor: color},
 selectedColor === index && styles.selectedColorOption
 ]}
 onPress={() => setSelectedColor(index)}
 />
 ))}
 </View>
 </View>

 <View style={styles.descriptionSection}>
 <Text style={styles.sectionTitle}>Description</Text>
 <Text style={styles.description}>
 {product.description || 'Sportswear is no longer under culture, it is no longer hip or cobbled together as it once was. Sport is fashion today. The top is oversized in fit and style, may need to size down.'}
 </Text>
 </View>
 </View>
 </ScrollView>

 <View style={styles.bottomContainer}>
 <TouchableOpacity
 style={styles.addToCartButton}
 onPress={handleAddToCart}
 activeOpacity={0.8}
 >
 <View style={styles.cartIcon}>
 <Text style={styles.cartIconText}></Text>
 </View>
 <Text style={styles.addToCartText}>Add To Cart</Text>
 </TouchableOpacity>
 </View>
 </SafeAreaView>
 );
};

const styles = StyleSheet.create({
