import React from 'react';
import {
 View,
 Text,
 Image,
 TouchableOpacity,
 StyleSheet,
} from 'react-native';

const ProductCard = ({product, onPress, horizontal = false}) => {
 const containerStyle = horizontal
 ? [styles.container, styles.horizontalContainer]
 : [styles.container, styles.verticalContainer];

 const imageStyle = horizontal
 ? styles.horizontalImage
 : styles.verticalImage;

 return (
 <TouchableOpacity
 style={containerStyle}
 onPress={() => onPress(product)}
 activeOpacity={0.8}
 >
 <Image
 source={{uri: product.image}}
 style={imageStyle}
 resizeMode="cover"
 />
 <View style={styles.info}>
 <Text style={styles.title} numberOfLines={2}>
 {product.title}
 </Text>
 <Text style={styles.price}>
 $ {product.price.toFixed(2)}
 </Text>
 </View>
 </TouchableOpacity>
 );
};

const styles = StyleSheet.create({
 container: {
 backgroundColor: 'white',
 borderRadius: 12,
