import React from 'react';
import {
 View,
 Text,
 TouchableOpacity,
 StyleSheet,
 ScrollView,
} from 'react-native';

const CategorySelector = ({categories, selectedCategory, onSelectCategory}) => {
 return (
 <ScrollView
 horizontal
 showsHorizontalScrollIndicator={false}
 style={styles.container}
 contentContainerStyle={styles.contentContainer}
 >
 {categories.map((category, index) => (
 <TouchableOpacity
 key={index}
 style={[
 styles.categoryButton,
 selectedCategory === category && styles.selectedCategoryButton
 ]}
 onPress={() => onSelectCategory(category)}
 >
 <View style={[
 styles.iconContainer,
 selectedCategory === category && styles.selectedIconContainer
 ]}>
 <Text style={[
 styles.icon,
 selectedCategory === category && styles.selectedIcon
 ]}>
 {getCategoryIcon(category)}
 </Text>
 </View>
 <Text style={[
 styles.categoryText,
 selectedCategory === category && styles.selectedCategoryText
 ]}>
 {category}
 </Text>
 </TouchableOpacity>
 ))}
 </ScrollView>
 );
};

const getCategoryIcon = (category) => {
 const icons = {
 'Women': '♀',
 'Men': '♂',
 'Accessories': '',
 'Beauty': '',
 };
 return icons[category] || '•';
};

const styles = StyleSheet.create({
 container: {
 paddingVertical: 10,
 },
 contentContainer: {
 paddingHorizontal: 20,
 },
 categoryButton: {
 alignItems: 'center',
 marginRight: 25,
 paddingVertical: 10,
 },
 iconContainer: {
 width: 50,
 height: 50,
 borderRadius: 25,
 backgroundColor: '#f5f5f5',
 justifyContent: 'center',
 alignItems: 'center',
 marginBottom: 8,
 },
 selectedIconContainer: {
 backgroundColor: '#333',
 },
 icon: {
 fontSize: 20,
 color: '#999',
 },
 selectedIcon: {
 color: 'white',
 },
 categoryText: {
 fontSize: 12,
 color: '#999',
 fontWeight: '500',
 },
 selectedCategoryText: {
 color: '#333',
 fontWeight: '600',
 },
});

export default CategorySelector;
```
